PRAGMA foreign_keys=ON;
CREATE TABLE settings(key TEXT PRIMARY KEY, value INTEGER NOT NULL CHECK(value BETWEEN 1 AND 100));
INSERT INTO settings(key,value) VALUES('auxiliary_weekly_limit',32);
CREATE TABLE users(email TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('direction','teacher')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE reservations(id TEXT PRIMARY KEY, space TEXT NOT NULL, date TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL CHECK(end>start), owner TEXT NOT NULL REFERENCES users(email), purpose TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX reservations_schedule ON reservations(space,date,start,end);
CREATE TRIGGER reservations_no_overlap BEFORE INSERT ON reservations BEGIN SELECT RAISE(ABORT,'reservation_conflict') WHERE EXISTS(SELECT 1 FROM reservations WHERE space=NEW.space AND date=NEW.date AND start<NEW.end AND end>NEW.start); END;
CREATE TABLE tasks(id TEXT PRIMARY KEY, title TEXT NOT NULL, owner TEXT NOT NULL REFERENCES users(email), due TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pendente','Em andamento','Concluída')), restricted INTEGER NOT NULL DEFAULT 0 CHECK(restricted IN (0,1)), creator TEXT NOT NULL REFERENCES users(email), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auxiliaries(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE substitutions(id TEXT PRIMARY KEY,date TEXT NOT NULL,week TEXT NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL CHECK(end>start),class TEXT NOT NULL,teacher TEXT NOT NULL,auxiliary TEXT REFERENCES auxiliaries(id),creator TEXT NOT NULL REFERENCES users(email));
CREATE INDEX substitutions_week ON substitutions(auxiliary,week);
CREATE TRIGGER substitutions_limit BEFORE UPDATE OF auxiliary,date,start,end,week ON substitutions WHEN NEW.auxiliary IS NOT NULL BEGIN SELECT RAISE(ABORT,'auxiliary_limit') WHERE (SELECT COUNT(*) FROM substitutions WHERE auxiliary=NEW.auxiliary AND week=NEW.week AND id!=NEW.id)>=(SELECT value FROM settings WHERE key='auxiliary_weekly_limit'); SELECT RAISE(ABORT,'auxiliary_conflict') WHERE EXISTS(SELECT 1 FROM substitutions WHERE auxiliary=NEW.auxiliary AND date=NEW.date AND start<NEW.end AND end>NEW.start AND id!=NEW.id); END;
CREATE TABLE xerox(id TEXT PRIMARY KEY,title TEXT NOT NULL,copies INTEGER NOT NULL CHECK(copies BETWEEN 1 AND 10000),deadline TEXT NOT NULL,requester TEXT NOT NULL REFERENCES users(email),status TEXT NOT NULL DEFAULT 'Aguardando aprovação' CHECK(status IN ('Aguardando aprovação','Aprovado','Devolvido para ajustes','Recusado','Em produção','Concluído')));
CREATE TABLE minutes(id TEXT PRIMARY KEY,title TEXT NOT NULL,date TEXT NOT NULL,participants TEXT NOT NULL,decisions TEXT NOT NULL,creator TEXT NOT NULL REFERENCES users(email));
CREATE TABLE events(id TEXT PRIMARY KEY,title TEXT NOT NULL,date TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('Reunião','Dia letivo','Feriado','Recesso','Conselho de classe','Evento escolar')),creator TEXT NOT NULL REFERENCES users(email));
-- No student tables: student-identifiable data requires a separate approved scope.

CREATE TRIGGER substitutions_insert_limit BEFORE INSERT ON substitutions WHEN NEW.auxiliary IS NOT NULL BEGIN SELECT RAISE(ABORT,'auxiliary_limit') WHERE (SELECT COUNT(*) FROM substitutions WHERE auxiliary=NEW.auxiliary AND week=NEW.week)>=(SELECT value FROM settings WHERE key='auxiliary_weekly_limit'); SELECT RAISE(ABORT,'auxiliary_conflict') WHERE EXISTS(SELECT 1 FROM substitutions WHERE auxiliary=NEW.auxiliary AND date=NEW.date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER reservations_update_no_overlap BEFORE UPDATE OF space,date,start,end ON reservations BEGIN SELECT RAISE(ABORT,'reservation_conflict') WHERE EXISTS(SELECT 1 FROM reservations WHERE space=NEW.space AND date=NEW.date AND start<NEW.end AND end>NEW.start AND id!=NEW.id); END;
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL REFERENCES users(email),action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE reservations ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE tasks ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE substitutions ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE auxiliaries ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE xerox ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE minutes ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE events ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE fixed_occupancy(id TEXT PRIMARY KEY,space TEXT NOT NULL,weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),start TEXT NOT NULL,end TEXT NOT NULL CHECK(end>start),from_date TEXT NOT NULL,to_date TEXT NOT NULL CHECK(to_date>=from_date),purpose TEXT NOT NULL,creator TEXT NOT NULL REFERENCES users(email),version INTEGER NOT NULL DEFAULT 1);
CREATE TRIGGER reservations_fixed_insert BEFORE INSERT ON reservations BEGIN SELECT RAISE(ABORT,'reservation_conflict') WHERE EXISTS(SELECT 1 FROM fixed_occupancy WHERE space=NEW.space AND weekday=CAST(strftime('%w',NEW.date) AS INTEGER) AND NEW.date BETWEEN from_date AND to_date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER reservations_fixed_update BEFORE UPDATE OF space,date,start,end ON reservations BEGIN SELECT RAISE(ABORT,'reservation_conflict') WHERE EXISTS(SELECT 1 FROM fixed_occupancy WHERE space=NEW.space AND weekday=CAST(strftime('%w',NEW.date) AS INTEGER) AND NEW.date BETWEEN from_date AND to_date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER fixed_occupancy_insert BEFORE INSERT ON fixed_occupancy BEGIN SELECT RAISE(ABORT,'reservation_conflict') WHERE EXISTS(SELECT 1 FROM fixed_occupancy WHERE space=NEW.space AND weekday=NEW.weekday AND from_date<=NEW.to_date AND to_date>=NEW.from_date AND start<NEW.end AND end>NEW.start) OR EXISTS(SELECT 1 FROM reservations WHERE space=NEW.space AND CAST(strftime('%w',date) AS INTEGER)=NEW.weekday AND date BETWEEN NEW.from_date AND NEW.to_date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER fixed_occupancy_update BEFORE UPDATE ON fixed_occupancy BEGIN SELECT RAISE(ABORT,'reservation_conflict') WHERE EXISTS(SELECT 1 FROM fixed_occupancy WHERE id!=NEW.id AND space=NEW.space AND weekday=NEW.weekday AND from_date<=NEW.to_date AND to_date>=NEW.from_date AND start<NEW.end AND end>NEW.start) OR EXISTS(SELECT 1 FROM reservations WHERE space=NEW.space AND CAST(strftime('%w',date) AS INTEGER)=NEW.weekday AND date BETWEEN NEW.from_date AND NEW.to_date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER substitutions_class_insert BEFORE INSERT ON substitutions BEGIN SELECT RAISE(ABORT,'class_conflict') WHERE EXISTS(SELECT 1 FROM substitutions WHERE class=NEW.class AND date=NEW.date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER substitutions_class_update BEFORE UPDATE OF class,date,start,end ON substitutions BEGIN SELECT RAISE(ABORT,'class_conflict') WHERE EXISTS(SELECT 1 FROM substitutions WHERE id!=NEW.id AND class=NEW.class AND date=NEW.date AND start<NEW.end AND end>NEW.start); END;
CREATE TRIGGER substitutions_active_insert BEFORE INSERT ON substitutions WHEN NEW.auxiliary IS NOT NULL BEGIN SELECT RAISE(ABORT,'auxiliary_inactive') WHERE NOT EXISTS(SELECT 1 FROM auxiliaries WHERE id=NEW.auxiliary AND active=1); END;
CREATE TRIGGER substitutions_active_update BEFORE UPDATE OF auxiliary ON substitutions WHEN NEW.auxiliary IS NOT NULL BEGIN SELECT RAISE(ABORT,'auxiliary_inactive') WHERE NOT EXISTS(SELECT 1 FROM auxiliaries WHERE id=NEW.auxiliary AND active=1); END;
CREATE TRIGGER auxiliaries_deactivate AFTER UPDATE OF active ON auxiliaries WHEN NEW.active=0 AND OLD.active=1 BEGIN UPDATE substitutions SET auxiliary=NULL,version=version+1 WHERE auxiliary=NEW.id AND date>=date('now','-3 hours'); END;
